import{_ as l,o as i,c as r,a2 as e}from"./chunks/framework.BXzK3EA4.js";const c=JSON.parse('{"title":"VPS 独立云盘使用指南","description":"","frontmatter":{"title":"VPS 独立云盘使用指南"},"headers":[],"relativePath":"ops-knowledge-base/vps/cloud-disk-guide.md","filePath":"ops-knowledge-base/vps/cloud-disk-guide.md","lastUpdated":1788259091000}'),t={name:"ops-knowledge-base/vps/cloud-disk-guide.md"};function o(p,a,s,n,h,d){return i(),r("div",null,[...a[0]||(a[0]=[e('<h2 id="用途" tabindex="-1">用途 <a class="header-anchor" href="#用途" aria-label="Permalink to &quot;用途&quot;">​</a></h2><p>本文档介绍 VPS 独立云盘（Cloud Disk）的创建、挂载、卸载及删除等基本操作，帮助客户快速了解独立云盘的使用方式。</p><p>独立云盘可作为服务器的额外数据存储空间，适用于扩容数据盘、存放业务数据或独立管理数据。</p><p><strong>适用产品：</strong></p><ul><li>VPS（Virtual Private Server）</li></ul><hr><h2 id="一、什么是独立云盘" tabindex="-1">一、什么是独立云盘？ <a class="header-anchor" href="#一、什么是独立云盘" aria-label="Permalink to &quot;一、什么是独立云盘？&quot;">​</a></h2><p>独立云盘是一种可独立管理的数据存储资源，可挂载至 VPS 使用。</p><p>与系统盘不同，独立云盘主要用于存储业务数据，可根据需要进行挂载、卸载及删除。</p><p>常见使用场景：</p><ul><li>扩展服务器存储空间</li><li>存放网站数据</li><li>存放数据库文件</li><li>数据与系统分离管理</li><li>独立备份业务数据</li></ul><hr><h2 id="二、创建独立云盘" tabindex="-1">二、创建独立云盘 <a class="header-anchor" href="#二、创建独立云盘" aria-label="Permalink to &quot;二、创建独立云盘&quot;">​</a></h2><p>操作步骤：</p><ol><li>登录 Raksmart 客户后台。</li><li>进入 购买中心**→ VPS**。</li><li>点击 <strong>购买独立云盘</strong>。</li><li>根据业务需求选择容量、地区及线路等配置。</li><li>完成订单支付后，即可在后台查看已购买的独立云盘。</li></ol><p><strong>说明：</strong></p><p>购买独立云盘时，请确保所选地区和需要挂载的 VPS 保持一致，否则无法进行挂载。</p><hr><h2 id="三、挂载独立云盘" tabindex="-1">三、挂载独立云盘 <a class="header-anchor" href="#三、挂载独立云盘" aria-label="Permalink to &quot;三、挂载独立云盘&quot;">​</a></h2><p>操作步骤：</p><ol><li>登录 Raksmart 客户后台。</li><li>进入 <strong>产品管理 → VPS → 独立云盘</strong>。</li><li>点击进入需要挂载的独立云盘。</li><li>点击 <strong>挂载</strong>。</li><li>在实例列表中选择需要挂载的 VPS。</li><li>确认后完成挂载。</li></ol><p><strong>说明：</strong></p><ul><li>独立云盘只能挂载至同一地区的 VPS。</li><li>如果实例列表中未显示目标 VPS，请确认该 VPS 是否与独立云盘属于相同地区。</li><li><strong>挂载独立云盘不会导致服务器重启，也不会影响当前业务运行。</strong></li></ul><hr><h2 id="四、挂载完成后需要做什么" tabindex="-1">四、挂载完成后需要做什么？ <a class="header-anchor" href="#四、挂载完成后需要做什么" aria-label="Permalink to &quot;四、挂载完成后需要做什么？&quot;">​</a></h2><p>完成后台挂载后，服务器仅识别到新增磁盘，<strong>不会自动完成分区、格式化及挂载文件系统</strong>。</p><p>客户需登录服务器，根据实际操作系统完成以下配置：</p><ul><li>查看新增磁盘；</li><li>创建磁盘分区（如需要）；</li><li>创建文件系统（首次使用时）；</li><li>挂载至指定目录；</li><li>配置开机自动挂载（如有需要）。</li></ul><p><strong>说明：</strong></p><p>后台完成挂载仅表示云盘已连接至服务器，实际投入使用仍需在系统内完成磁盘初始化及挂载操作。</p><hr><h2 id="五、卸载独立云盘" tabindex="-1">五、卸载独立云盘 <a class="header-anchor" href="#五、卸载独立云盘" aria-label="Permalink to &quot;五、卸载独立云盘&quot;">​</a></h2><p>如需将独立云盘从 VPS 中移除，可在后台执行卸载操作。</p><p>操作步骤：</p><ol><li>登录 Raksmart 客户后台。</li><li>进入 <strong>产品管理 →VPS → 独立云盘</strong>。</li><li>选择对应云盘。</li><li>点击 <strong>卸载</strong>。</li><li>确认解绑服务器。</li></ol><p><strong>建议：</strong></p><p>卸载前，请先登录服务器卸载（Unmount）文件系统，并确认没有程序正在使用该磁盘，以避免数据异常或文件损坏。</p><p><strong>说明：</strong></p><p>卸载独立云盘不会删除云盘中的数据。</p><hr><h2 id="六、常见问题" tabindex="-1">六、常见问题 <a class="header-anchor" href="#六、常见问题" aria-label="Permalink to &quot;六、常见问题&quot;">​</a></h2><h3 id="q1-为什么挂载时找不到需要绑定的-vps" tabindex="-1">Q1：为什么挂载时找不到需要绑定的 VPS？ <a class="header-anchor" href="#q1-为什么挂载时找不到需要绑定的-vps" aria-label="Permalink to &quot;Q1：为什么挂载时找不到需要绑定的 VPS？&quot;">​</a></h3><p>独立云盘只能挂载至<strong>同一地区、同一线路</strong>的 VPS。</p><p>如果后台未显示目标实例，请确认云盘与 VPS 是否属于相同地区及线路。</p><hr><h3 id="q2-挂载独立云盘会导致服务器重启吗" tabindex="-1">Q2：挂载独立云盘会导致服务器重启吗？ <a class="header-anchor" href="#q2-挂载独立云盘会导致服务器重启吗" aria-label="Permalink to &quot;Q2：挂载独立云盘会导致服务器重启吗？&quot;">​</a></h3><p>不会。</p><p>后台挂载独立云盘不会重启服务器，也不会中断当前业务。</p><hr><h3 id="q3-为什么挂载完成后系统中没有立即看到可以使用的磁盘空间" tabindex="-1">Q3：为什么挂载完成后系统中没有立即看到可以使用的磁盘空间？ <a class="header-anchor" href="#q3-为什么挂载完成后系统中没有立即看到可以使用的磁盘空间" aria-label="Permalink to &quot;Q3：为什么挂载完成后系统中没有立即看到可以使用的磁盘空间？&quot;">​</a></h3><p>后台完成挂载后，还需要登录服务器完成磁盘初始化操作。</p><p>包括：</p><ul><li>分区（如需要）</li><li>格式化（首次使用）</li><li>挂载文件系统</li></ul><p>完成以上操作后，云盘才能正常使用。</p><hr><h3 id="q4-卸载独立云盘会删除数据吗" tabindex="-1">Q4：卸载独立云盘会删除数据吗？ <a class="header-anchor" href="#q4-卸载独立云盘会删除数据吗" aria-label="Permalink to &quot;Q4：卸载独立云盘会删除数据吗？&quot;">​</a></h3><p>不会。</p><p>卸载仅解除云盘与服务器的关联，不会自动删除云盘中的数据。</p><hr><h3 id="q5-独立云盘回收后还能恢复数据吗" tabindex="-1">Q5：独立云盘回收后还能恢复数据吗？ <a class="header-anchor" href="#q5-独立云盘回收后还能恢复数据吗" aria-label="Permalink to &quot;Q5：独立云盘回收后还能恢复数据吗？&quot;">​</a></h3><p>不能。</p><p>独立云盘一旦因到期未续费、退款或其他原因被系统回收，云盘中的数据将无法恢复。</p><p>建议您提前备份重要数据，以免造成数据丢失。</p><hr><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><p>⚠️ 独立云盘仅支持挂载至<strong>同一地区</strong> VPS，不支持跨地区或跨线路挂载。</p><p>⚠️ 后台完成挂载后，还需登录服务器完成磁盘初始化及挂载操作，否则系统无法正常使用新增磁盘。</p><p>⚠️ 挂载、卸载独立云盘不会导致 VPS 自动重启。</p><p>⚠️如独立云盘到期未续费、申请退款或因其他原因被系统回收，云盘中的数据将无法恢复。请提前备份重要数据，避免数据丢失。</p><hr>',70)])])}const P=l(t,[["render",o]]);export{c as __pageData,P as default};
